import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ResourcePackStack{TexturePackRequired: true, TexturePacks: []protocol.StackResourcePack{{UUID: "5a1c",
# Version: "1.2.3", SubPackName: "hd"}, {UUID: "6b2d", Version: "0.0.1"}}, BaseGameVersion: "1.26.44", Experiments:
# []protocol.ExperimentData{{Name: "gametest", Enabled: true}, {Name: "data_driven_biomes"}},
# ExperimentsPreviouslyToggled: true, IncludeEditorPacks: true}
STACK = bytes.fromhex(
    "0102043561316305312e322e33026864043662326405302e302e310007312e32362e3434020000000867616d65746573740112"
    "646174615f64726976656e5f62696f6d6573000101"
)

# generated by gophertunnel b8bd735:
# packet.ResourcePackStack{IncludeEditorPacks: true}
EDITOR_ONLY = bytes.fromhex("000000000000000001")

GOLDENS = [
    pytest.param(
        v2225.ResourcePackStackPacket(
            texture_pack_required=True,
            texture_pack_ids_and_versions=[
                v2225.PackInstanceId(pack_id="5a1c", version="1.2.3", subpack_name="hd"),
                v2225.PackInstanceId(pack_id="6b2d", version="0.0.1"),
            ],
            base_game_version="1.26.44",
            experiments=v2225.Experiments(
                toggles=[
                    v2225.ExperimentToggle(name="gametest", enabled=True),
                    v2225.ExperimentToggle(name="data_driven_biomes", enabled=False),
                ],
                experiments_ever_toggled=True,
            ),
            include_editor_packs=True,
        ),
        STACK,
        id="full",
    ),
    pytest.param(v2225.ResourcePackStackPacket(include_editor_packs=True), EDITOR_ONLY, id="editor-only"),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_resource_pack_stack_is_packet_7(version):
    assert version.PACKETS[7] is version.ResourcePackStackPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_stack_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_stack_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_pack_count_is_a_varint():
    packet = v2225.ResourcePackStackPacket(texture_pack_ids_and_versions=[v2225.PackInstanceId()] * 300)
    wire = bytes(packet)
    assert len(wire) == 910
    assert v2225.ResourcePackStackPacket.from_bytes(wire) == packet
